import{_ as o,o as i,c as t,aj as l}from"./chunks/framework.BZR1KcQy.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"docs/wi/ovirt.md","filePath":"docs/wi/ovirt.md","lastUpdated":1788534566000}'),r={name:"docs/wi/ovirt.md"};function c(d,e,s,a,n,g){return i(),t("div",null,e[0]||(e[0]=[l('<ul><li>это чисто метапакет для нашей сборки</li><li>веб интерфейс</li></ul><p>То, что уже собрано для Альта</p><p>Давайте разберем ваш список и добавим важные детали.</p><h3 id="🏗️-компоненты-которые-потребуется-собрать" tabindex="-1">🏗️ Компоненты, которые потребуется собрать <a class="header-anchor" href="#🏗️-компоненты-которые-потребуется-собрать" aria-label="Permalink to &quot;🏗️ Компоненты, которые потребуется собрать&quot;">​</a></h3><p>Вы правы, эти три компонента являются основой для сборки:</p><ul><li><strong><code>ovirt-engine</code></strong>: Это сердце oVirt — управляющий сервер (менеджер). Это самый сложный и требовательный к зависимостям компонент. <a href="https://github.com/oVirt/ovirt-engine" target="_blank" rel="noreferrer">https://github.com/oVirt/ovirt-engine</a></li><li><strong><code>ovirt-web-ui</code></strong>: Это веб-интерфейс для пользователей (VM Portal). Он работает поверх <code>ovirt-engine</code> и, скорее всего, потребует сборки. <a href="https://github.com/oVirt/ovirt-web-ui" target="_blank" rel="noreferrer">https://github.com/oVirt/ovirt-web-ui</a></li><li><strong><code>ovirt-host</code></strong>: Ваше понимание верное — это <strong>метапакет</strong>. Он не содержит кода, а только перечисляет зависимости, необходимые для превращения сервера в хост виртуализации oVirt (например, <code>vdsm</code>, <code>libvirt</code>, <code>qemu-kvm</code>). Собрать его будет несложно, но его главная цель — упростить установку всех нужных пакетов на хост. <a href="https://github.com/oVirt/ovirt-host" target="_blank" rel="noreferrer">https://github.com/oVirt/ovirt-host</a></li></ul><h3 id="✅-компоненты-уже-доступные-в-alt-linux" tabindex="-1">✅ Компоненты, уже доступные в ALT Linux <a class="header-anchor" href="#✅-компоненты-уже-доступные-в-alt-linux" aria-label="Permalink to &quot;✅ Компоненты, уже доступные в ALT Linux&quot;">​</a></h3><p>Вы совершенно правы, эти пакеты уже есть в репозиториях Sisyphus, и их <strong>не нужно собирать</strong> самостоятельно. Их можно установить через штатный менеджер пакетов:</p><ul><li><strong><code>ovirt-imageio</code></strong>: Служба для передачи дисковых образов. <a href="https://packages.altlinux.org/ru/sisyphus/srpms/ovirt-imageio/" target="_blank" rel="noreferrer">https://packages.altlinux.org/ru/sisyphus/srpms/ovirt-imageio/</a></li><li><strong><code>ovirt-vmconsole</code></strong>: Прокси для консольного доступа к виртуальным машинам. <a href="https://packages.altlinux.org/ru/sisyphus/srpms/ovirt-vmconsole/" target="_blank" rel="noreferrer">https://packages.altlinux.org/ru/sisyphus/srpms/ovirt-vmconsole/</a></li><li><strong><code>libgovirt</code></strong>: Библиотека для работы с REST API oVirt. <a href="https://packages.altlinux.org/ru/sisyphus/srpms/libgovirt/" target="_blank" rel="noreferrer">https://packages.altlinux.org/ru/sisyphus/srpms/libgovirt/</a></li><li><strong><code>python3-module-ovirt-engine-sdk</code></strong>: Python SDK для взаимодействия с API oVirt Engine. <a href="https://packages.altlinux.org/ru/sisyphus/srpms/python3-module-ovirt-engine-sdk/" target="_blank" rel="noreferrer">https://packages.altlinux.org/ru/sisyphus/srpms/python3-module-ovirt-engine-sdk/</a></li><li><strong><code>ovirt-guest-agent</code></strong>: Агент, который устанавливается внутрь гостевых виртуальных машин. <a href="https://packages.altlinux.org/ru/sisyphus/srpms/ovirt-guest-agent/" target="_blank" rel="noreferrer">https://packages.altlinux.org/ru/sisyphus/srpms/ovirt-guest-agent/</a></li></ul><h3 id="⚠️-важные-моменты-и-отсутствующие-компоненты" tabindex="-1">⚠️ Важные моменты и отсутствующие компоненты <a class="header-anchor" href="#⚠️-важные-моменты-и-отсутствующие-компоненты" aria-label="Permalink to &quot;⚠️ Важные моменты и отсутствующие компоненты&quot;">​</a></h3><p>При планировании работы учтите, что для полноценной установки могут потребоваться и другие компоненты, которые, скорее всего, также придется собирать:</p><ul><li><strong>VDSM (Virtual Desktop and Server Manager)</strong>: Это главный агент, который работает на каждом хосте и через который <code>ovirt-engine</code> управляет виртуальными машинами. Это критически важный компонент, и его нет в вашем списке. <a href="https://github.com/oVirt/vdsm" target="_blank" rel="noreferrer">https://github.com/oVirt/vdsm</a></li><li><strong><code>ovirt-engine-dwh</code></strong>: Компонент Data Warehouse, который собирает историческую информацию о работе платформы для отчетов. <a href="https://github.com/oVirt/ovirt-dwh" target="_blank" rel="noreferrer">https://github.com/oVirt/ovirt-dwh</a></li><li><strong><code>ovirt-engine-appliance</code></strong>: Готовый образ виртуальной машины для быстрого развертывания self-hosted engine. <a href="https://github.com/oVirt/ovirt-appliance" target="_blank" rel="noreferrer">https://github.com/oVirt/ovirt-appliance</a></li><li><strong>Зависимости <code>ovirt-engine</code></strong>: Это самый сложный момент. У <code>ovirt-engine</code> очень много зависимостей (Java-библиотеки, Wildfly и т.д.). Проект oVirt даже поддерживает отдельный репозиторий <code>ovirt-engine-build-dependencies</code> для упрощения их сборки. Вам почти наверняка придется собирать и их.</li></ul><p>Ниже приведён <strong>полный список всех пакетов</strong>, которые встречаются в <code>Requires</code> и <code>Suggests</code> (только <code>postfix</code>) в представленном spec-файле <code>ovirt-host</code>. Я выписал все имена <strong>без учёта условий</strong> (архитектура, версия RHEL) — так вы сможете видеть все возможные зависимости, которые могут потребоваться для сборки или установки на ALT Linux.</p><blockquote><p><strong>Важно:</strong> В ALT Linux названия некоторых пакетов могут отличаться (например, <code>python3-firewall</code> часто называется <code>python3-module-firewall</code>). Сверяйтесь с репозиториями вашего дистрибутива.</p></blockquote><hr><h3 id="список-пакетов-алфавитныи-порядок" tabindex="-1">Список пакетов (алфавитный порядок) <a class="header-anchor" href="#список-пакетов-алфавитныи-порядок" aria-label="Permalink to &quot;Список пакетов (алфавитный порядок)&quot;">​</a></h3><ul><li><code>aide</code></li><li><code>audispd-plugins</code></li><li><code>ceph-common</code></li><li><code>clevis-dracut</code></li><li><code>cockpit</code></li><li><code>cockpit-ovirt-dashboard</code></li><li><code>cockpit-system</code></li><li><code>collectd</code></li><li><code>collectd-disk</code></li><li><code>collectd-netlink</code></li><li><code>collectd-virt</code></li><li><code>collectd-write_http</code></li><li><code>collectd-write_syslog</code></li><li><code>cracklib-dicts</code></li><li><code>dmidecode</code></li><li><code>dracut-fips</code></li><li><code>firewalld</code></li><li><code>glusterfs</code></li><li><code>ipa-client</code></li><li><code>iperf3</code></li><li><code>kexec-tools</code></li><li><code>libestr</code></li><li><code>libfastjson</code></li><li><code>liblognorm</code></li><li><code>libvirt</code></li><li><code>libvirt-admin</code></li><li><code>mailx</code></li><li><code>microcode_ctl</code></li><li><code>net-snmp</code></li><li><code>net-snmp-utils</code></li><li><code>NetworkManager-config-server</code></li><li><code>nvme-cli</code></li><li><code>opensc</code></li><li><code>openscap</code></li><li><code>ovirt-hosted-engine-setup</code></li><li><code>ovirt-imageio-client</code></li><li><code>ovirt-provider-ovn-driver</code></li><li><code>ovirt-vmconsole</code></li><li><code>ovirt-vmconsole-host</code></li><li><code>pcsc-lite</code></li><li><code>postfix</code> (как <strong>Suggests</strong>)</li><li><code>python3-firewall</code></li><li><code>python3-os-brick</code></li><li><code>rng-tools</code></li><li><code>rsyslog</code></li><li><code>rsyslog-elasticsearch</code></li><li><code>rsyslog-mmjsonparse</code></li><li><code>rsyslog-mmnormalize</code></li><li><code>rsyslog-openssl</code></li><li><code>s-nail</code></li><li><code>scap-security-guide</code></li><li><code>server(smtp)</code> — виртуальный пакет, зависит от MTA</li><li><code>smartmontools</code></li><li><code>socat</code></li><li><code>sscg</code></li><li><code>sysstat</code></li><li><code>tar</code></li><li><code>tcpdump</code></li><li><code>tmux</code></li><li><code>tuned</code></li><li><code>util-linux</code></li><li><code>vdsm</code> (требуется версия ≥ 4.50.0.11)</li><li><code>vdsm-client</code> (требуется версия ≥ 4.50.0.11)</li></ul>',17)]))}const h=o(r,[["render",c]]);export{u as __pageData,h as default};
